$.fn.up_flash_background=function(a){a=$.extend({},{color:"rgb(243, 243, 21)",duration:750,easing:"easeOutQuad",callback:null},a);return this.each(function(){if((typeof $(this).data("original-background-color")=="undefined")){$(this).data("original-background-color",$(this).css("backgroundColor"))}$(this).stop().css("backgroundColor",a.color);$(this).animate({backgroundColor:$(this).data("original-background-color")},a.duration,a.easing,function(){if(typeof a.callback=="function"&&a.callback!=null){a.callback()}});return $(this)})};$.fn.up_flash_color=function(a){a=$.extend({},{color:"rgb(243, 243, 21)",duration:750,easing:"easeOutQuad",callback:null},a);return this.each(function(){if((typeof $(this).data("original-color")=="undefined")){$(this).data("original-color",$(this).css("color"))}$(this).stop().css("color",a.color);$(this).animate({color:$(this).data("original-color")},a.duration,a.easing,function(){if(typeof a.callback=="function"&&a.callback!=null){a.callback()}});return $(this)})};$.fn.up_flash=function(a){this.up_flash_background(a)};